import{_ as i,c as a,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const p=JSON.parse('{"title":"Resilient Architecture and Distributed Systems — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-12-resilient-distributed-systems.md","filePath":"practice/node-js/module-12-resilient-distributed-systems.md"}'),s={name:"practice/node-js/module-12-resilient-distributed-systems.md"};function n(l,e,o,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="resilient-architecture-and-distributed-systems-—-practice" tabindex="-1">Resilient Architecture and Distributed Systems — practice <a class="header-anchor" href="#resilient-architecture-and-distributed-systems-—-practice" aria-label="Permalink to “Resilient Architecture and Distributed Systems — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-12-resilient-distributed-systems.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="_17-failure-driven-exercises" tabindex="-1">17. Failure-driven exercises <a class="header-anchor" href="#_17-failure-driven-exercises" aria-label="Permalink to “17. Failure-driven exercises”">​</a></h2><h3 id="exercise-1-duplicate-payment-request" tabindex="-1">Exercise 1: Duplicate payment request <a class="header-anchor" href="#exercise-1-duplicate-payment-request" aria-label="Permalink to “Exercise 1: Duplicate payment request”">​</a></h3><p>A client times out after the payment provider charges successfully. It repeats <code>POST /payments</code>.</p><p>Design:</p><ul><li>the idempotency-key contract;</li><li>durable processing states;</li><li>request-hash validation;</li><li>provider operation identifiers;</li><li>behavior while the first attempt is still processing;</li><li>reconciliation for an unknown provider outcome.</li></ul><h3 id="exercise-2-consumer-crash-after-side-effect" tabindex="-1">Exercise 2: Consumer crash after side effect <a class="header-anchor" href="#exercise-2-consumer-crash-after-side-effect" aria-label="Permalink to “Exercise 2: Consumer crash after side effect”">​</a></h3><p>A consumer updates inventory and crashes before acknowledging the message. The broker redelivers it.</p><p>Implement a deduplication record in the same transaction as the inventory change. Explain why an in-memory set is insufficient.</p><h3 id="exercise-3-database-commit-plus-event-publication" tabindex="-1">Exercise 3: Database commit plus event publication <a class="header-anchor" href="#exercise-3-database-commit-plus-event-publication" aria-label="Permalink to “Exercise 3: Database commit plus event publication”">​</a></h3><p>An order exists in the database, but its event was lost during a broker outage.</p><p>Design an outbox table and relay. Define claim/locking behavior, stable event IDs, retry policy, cleanup, metrics, and consumer idempotency.</p><h3 id="exercise-4-retry-storm" tabindex="-1">Exercise 4: Retry storm <a class="header-anchor" href="#exercise-4-retry-storm" aria-label="Permalink to “Exercise 4: Retry storm”">​</a></h3><p>A dependency slows down. Three application layers each retry three times. Connection pools fill and the dependency receives more traffic while unhealthy.</p><p>Choose one retry owner. Add a deadline, jitter, a concurrency limit, and a circuit breaker. Define which errors remain retryable.</p><h3 id="exercise-5-cache-stampede" tabindex="-1">Exercise 5: Cache stampede <a class="header-anchor" href="#exercise-5-cache-stampede" aria-label="Permalink to “Exercise 5: Cache stampede”">​</a></h3><p>A popular product key expires on 50 instances at once. All instances query the database.</p><p>Compare TTL jitter, per-instance single-flight, a shared refresh lock, and stale-while-revalidate. Explain the remaining failure cases.</p><h3 id="exercise-6-stale-lock-holder" tabindex="-1">Exercise 6: Stale lock holder <a class="header-anchor" href="#exercise-6-stale-lock-holder" aria-label="Permalink to “Exercise 6: Stale lock holder”">​</a></h3><p>A worker pauses past its lease, then resumes after another worker acquired the lock and wrote newer data.</p><p>Add fencing tokens enforced by the protected store, or redesign the write as a conditional state transition.</p><h3 id="exercise-7-multi-service-order-flow" tabindex="-1">Exercise 7: Multi-service order flow <a class="header-anchor" href="#exercise-7-multi-service-order-flow" aria-label="Permalink to “Exercise 7: Multi-service order flow”">​</a></h3><p>Inventory reservation succeeds, payment authorization fails, and releasing inventory temporarily fails.</p><p>Model saga states, retries, compensation, deadlines, and the user-visible outcome. Add a reconciliation query for reservations stuck beyond their deadline.</p><p>For each exercise, identify the source of truth, the uncertain window, the recovery owner, and the evidence operators need.</p><hr><h2 id="_18-final-review-checklist" tabindex="-1">18. Final review checklist <a class="header-anchor" href="#_18-final-review-checklist" aria-label="Permalink to “18. Final review checklist”">​</a></h2><h3 id="architecture-and-boundaries" tabindex="-1">Architecture and boundaries <a class="header-anchor" href="#architecture-and-boundaries" aria-label="Permalink to “Architecture and boundaries”">​</a></h3><ul><li>[ ] Explain why a modular monolith is often the best starting point.</li><li>[ ] Justify a service boundary with ownership, scaling, isolation, or release needs.</li><li>[ ] Keep business policy behind explicit interfaces.</li><li>[ ] Identify consistency, trust, and failure boundaries.</li><li>[ ] Choose synchronous communication only when the result is needed now.</li></ul><h3 id="messaging" tabindex="-1">Messaging <a class="header-anchor" href="#messaging" aria-label="Permalink to “Messaging”">​</a></h3><ul><li>[ ] Explain at-most-once, at-least-once, and effectively-once effects.</li><li>[ ] Distinguish publisher confirmation from consumer acknowledgement.</li><li>[ ] Acknowledge only after durable processing.</li><li>[ ] Make consumers idempotent with a durable uniqueness rule.</li><li>[ ] Design bounded retries, backoff, jitter, and a dead-letter workflow.</li><li>[ ] Choose partition keys and concurrency from real ordering and capacity needs.</li><li>[ ] Version message contracts and test rolling compatibility.</li></ul><h3 id="data-consistency" tabindex="-1">Data consistency <a class="header-anchor" href="#data-consistency" aria-label="Permalink to “Data consistency”">​</a></h3><ul><li>[ ] Use an outbox when local state and publication intent must commit together.</li><li>[ ] Expect the outbox relay to publish duplicates.</li><li>[ ] Model sagas as durable state machines.</li><li>[ ] Treat compensation as a new fallible business operation, not a rollback.</li><li>[ ] Expose honest pending, completed, and failed states.</li><li>[ ] Build reconciliation for important workflows.</li></ul><h3 id="resilience" tabindex="-1">Resilience <a class="header-anchor" href="#resilience" aria-label="Permalink to “Resilience”">​</a></h3><ul><li>[ ] Set one responsible retry policy within a time budget.</li><li>[ ] Scope circuit breakers to meaningful dependency operations.</li><li>[ ] Isolate scarce capacity with bulkheads and concurrency limits.</li><li>[ ] Define cache freshness, invalidation, size, failure, and stampede behavior.</li><li>[ ] Prefer constraints and conditional writes over distributed locks.</li><li>[ ] Use fencing when a stale lease holder could corrupt state.</li><li>[ ] Drain message consumers safely during shutdown.</li></ul>',37)])])}const m=i(s,[["render",n]]);export{p as __pageData,m as default};
